	const EmbeddedFont* find_embedded_font(const char* name)
	{
		if (name == nullptr)
			return nullptr;

		for (const EmbeddedFont& f : TABLE)
			if (std::strcmp(f.name, name) == 0)
				return &f;

		return nullptr;
	}
